import { store, getContext } from '@wordpress/interactivity';

const { state } = store( 'offline-commerce', {
    state: {
        get cartTotal() {
            return getContext().cart.reduce((t, i) => t + (i.price * i.qty), 0);
        },
        get isCartEmpty() { 
            return getContext().cart.length === 0; 
        }
    },
    actions: {
        addToCart: ( e ) => {
            const ctx = getContext();
            const prod = JSON.parse( e.target.dataset.product );
            const ext = ctx.cart.find( i => i.id === prod.id );
            ext ? ext.qty += 1 : ctx.cart.push( { ...prod, qty: 1 } );
        },
        checkoutWhatsApp: () => {
            let msg = "Pedido offline (Jinotega):\n" + getContext().cart.map(i => `- ${i.qty}x ${i.title} (C$${i.price})`).join('\n');
            window.open(`https://wa.me/50588888888?text=${encodeURIComponent(msg + `\nTotal: C$${state.cartTotal}`)}`);
        }
    }
});